'use client';

import { useState } from 'react';
import { Button } from '@/components/ui/Button';
import { EnquiryModal } from '@/components/leads/EnquiryModal';
import { CallNowButton } from '@/components/leads/CallNowButton';

interface PropertyActionsProps {
  propertyId: number;
  propertyTitle: string;
}

type ModalMode = 'callback' | 'enquiry' | null;

export function PropertyActions({ propertyId, propertyTitle }: PropertyActionsProps) {
  const [modalMode, setModalMode] = useState<ModalMode>(null);

  return (
    <div className="space-y-4">
      <div className="flex flex-wrap gap-3">
        <CallNowButton
          surface="property_detail"
          propertyId={propertyId}
          className="flex-1 min-w-[160px] inline-flex items-center justify-center rounded-lg bg-brand-navy px-8 py-4 text-base font-semibold text-white transition-all duration-200 hover:bg-brand-navy-dark focus:outline-none focus:ring-2 focus:ring-brand-navy focus:ring-offset-2"
        >
          <svg
            className="h-5 w-5 mr-2"
            fill="none"
            viewBox="0 0 24 24"
            stroke="currentColor"
            aria-hidden="true"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M3 5a2 2 0 012-2h3.28a1 1 0 01.948.684l1.498 4.493a1 1 0 01-.502 1.21l-2.257 1.13a11.042 11.042 0 005.516 5.516l1.13-2.257a1 1 0 011.21-.502l4.493 1.498a1 1 0 01.684.949V19a2 2 0 01-2 2h-1C9.716 21 3 14.284 3 6V5z"
            />
          </svg>
          Call Now
        </CallNowButton>
        <Button
          variant="secondary"
          size="lg"
          className="flex-1 min-w-[160px]"
          onClick={() => setModalMode('callback')}
        >
          <svg
            className="h-5 w-5 mr-2"
            fill="none"
            viewBox="0 0 24 24"
            stroke="currentColor"
            aria-hidden="true"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z"
            />
          </svg>
          Request a Call
        </Button>
      </div>

      <Button variant="gold" size="lg" className="w-full" onClick={() => setModalMode('enquiry')}>
        <svg
          className="h-5 w-5 mr-2"
          fill="none"
          viewBox="0 0 24 24"
          stroke="currentColor"
          aria-hidden="true"
        >
          <path
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeWidth={2}
            d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z"
          />
        </svg>
        Enquire About This Property
      </Button>

      {modalMode === 'callback' && (
        <EnquiryModal
          mode="callback"
          context={{ propertyId, propertyTitle }}
          surface="property_detail"
          onClose={() => setModalMode(null)}
        />
      )}
      {modalMode === 'enquiry' && (
        <EnquiryModal
          mode="property"
          context={{ propertyId, propertyTitle }}
          surface="property_detail"
          onClose={() => setModalMode(null)}
        />
      )}
    </div>
  );
}
